const STORAGE_KEY='yanabea_individual_quote_lite_v1';
const PHONE_DEFAULT=['+966555509419','+966568666399','+966549781111','+966546777511'];
const MAX_OFFERS=8;
const MAX_FONT_FILE_SIZE=2.5*1024*1024;
const PDF_FONT_SPECS={
  expo:{family:'ExpoArabic',uploadId:'fontUploadExpo',nameId:'fontNameExpo',builtInFile:'ExpoArabic-SemiBold.ttf'},
  gess:{family:'GESSTwo',uploadId:'fontUploadGess',nameId:'fontNameGess',builtInFile:'GE-SS-Two-Bold.otf'},
  helveticaBold:{family:'HelveticaBold',uploadId:'fontUploadHelveticaBold',nameId:'fontNameHelveticaBold',builtInFile:'Helvetica-Bold.ttf'},
  helveticaRounded:{family:'HelveticaRounded',uploadId:'fontUploadHelveticaRounded',nameId:'fontNameHelveticaRounded',builtInFile:'Helvetica-Rounded-Bold.otf'}
};
const BUILTIN_FONT_LOADS=['600 16px ExpoArabic','700 16px GESSTwo','700 16px HelveticaBold','700 16px HelveticaRounded'];
const AUTH_HASH='db031c72ba245b0d6de8febc3797849ada2e764fbd783251f21cd823da263883';

const uid=()=>Math.random().toString(36).slice(2,11)+Date.now().toString(36).slice(-4);
const localISODate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>localISODate(new Date());
const tomorrow=()=>{const d=new Date();d.setDate(d.getDate()+1);return localISODate(d)};
const clone=v=>JSON.parse(JSON.stringify(v));
const safeId=v=>/^[A-Za-z0-9_-]{1,64}$/.test(String(v||''))?String(v):uid();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{
  const n=Number(String(v??'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٬,\s]/g,'').replace('٫','.'));
  return Number.isFinite(n)?n:0;
};
const money=v=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(num(v));
const dateLabel=v=>{if(!v)return'—';const p=String(v).split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:v};
const nightsText=n=>Number(n)===1?'1 ليلة':`${Number(n)||0} ليالٍ`;

function defaultOffer(){
  return {id:uid(),hotelMode:'list',hotelId:'',hotelName:'',checkIn:today(),checkOut:tomorrow(),roomType:'',mealPlan:'',view:'',pricingMode:'nightly',nightlyPrice:'',weekdayPrice:'',weekendPrice:'',totalPrice:'',extraBed:'',notes:''};
}
function defaultData(){
  return {
    draft:{customerName:'',quoteDate:today(),intro:'نسعد بإبلاغك بتفاصيل الحجز كالتالي:',currency:'ريال سعودي',notes:'الأسعار قابلة للتغيير حسب الإمكانية وقت التأكيد.',closing:'يسعدنا خدمتك، ولتأكيد الحجز يرجى التواصل معنا وإرسال بيانات النزلاء.',items:[defaultOffer()]},
    library:[],
    settings:{companyName:'ينابيع الهدى المتميزة',companyLine:'سكن مطمئن لرحلة مباركة',phones:PHONE_DEFAULT.join('، '),logo:ORIGINAL_LOGO,pdfFonts:{}},
    activeId:''
  };
}

let app=load();

function normalize(){
  const d=defaultData();
  app=app&&typeof app==='object'?app:d;
  app.draft=Object.assign(d.draft,app.draft||{});
  app.library=Array.isArray(app.library)?app.library.slice(0,250):[];
  const libraryIds=new Set();
  app.library=app.library.filter(x=>x&&typeof x==='object'&&x.data&&typeof x.data==='object').map(x=>{
    let id=safeId(x.id);
    while(libraryIds.has(id))id=uid();
    libraryIds.add(id);
    return {...x,id,title:String(x.title||'عرض محفوظ')};
  });
  app.settings=Object.assign(d.settings,app.settings||{});app.settings.logo=ORIGINAL_LOGO;
  app.settings.pdfFonts=app.settings.pdfFonts&&typeof app.settings.pdfFonts==='object'?app.settings.pdfFonts:{};
  Object.keys(PDF_FONT_SPECS).forEach(key=>{
    const item=app.settings.pdfFonts[key];
    app.settings.pdfFonts[key]=item&&typeof item==='object'?{name:String(item.name||''),data:String(item.data||'')}:{name:'',data:''};
  });
  if(!app.settings.companyLine||app.settings.companyLine==='خدمات الفنادق والحجوزات')app.settings.companyLine='سكن مطمئن لرحلة مباركة';
  app.settings.phones=normalizePhones(app.settings.phones||PHONE_DEFAULT.join('، '));
  app.draft.items=Array.isArray(app.draft.items)&&app.draft.items.length?app.draft.items.slice(0,MAX_OFFERS):[defaultOffer()];
  const offerIds=new Set();
  app.draft.items=app.draft.items.map(x=>{
    const o=Object.assign(defaultOffer(),x||{}),known=findHotel(o.hotelName,o.hotelId);
    o.id=safeId(o.id);
    while(offerIds.has(o.id))o.id=uid();
    offerIds.add(o.id);
    if(!['list','custom'].includes(o.hotelMode))o.hotelMode=known?'list':(o.hotelName?'custom':'list');
    if(o.hotelMode==='list'&&known){o.hotelId=known.id;o.hotelName=known.name}
    return o;
  });
}

function load(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||defaultData()}catch(e){return defaultData()}}

let storageWarningShown=false;
function persist(){
  try{
    // Do not call normalize() here: it replaces offer object references while
    // input listeners are still using them, which can drop later keystrokes.
    localStorage.setItem(STORAGE_KEY,JSON.stringify(app));
    storageWarningShown=false;
    return true;
  }catch(e){
    console.error('Unable to save quote data',e);
    if(!storageWarningShown){
      storageWarningShown=true;
      toast('تعذر الحفظ على الجهاز. صدّر نسخة احتياطية ثم حرر مساحة التخزين.');
    }
    return false;
  }
}


const loadedPdfFonts={};
const loadedPdfFontKeys={};

function pdfFontState(){
  if(!app.settings.pdfFonts||typeof app.settings.pdfFonts!=='object')app.settings.pdfFonts={};
  Object.keys(PDF_FONT_SPECS).forEach(key=>{
    if(!app.settings.pdfFonts[key]||typeof app.settings.pdfFonts[key]!=='object')app.settings.pdfFonts[key]={name:'',data:''};
  });
  return app.settings.pdfFonts;
}

async function ensurePdfFonts(force=false){
  if(!('FontFace' in window)||!document.fonts)return;
  await Promise.all(BUILTIN_FONT_LOADS.map(font=>document.fonts.load(font).catch(()=>[])));
  const fonts=pdfFontState();
  for(const [key,spec] of Object.entries(PDF_FONT_SPECS)){
    const item=fonts[key]||{};
    const data=String(item.data||'');
    if(!data)continue;
    const cacheKey=`${data.length}:${data.slice(-32)}`;
    if(!force&&loadedPdfFontKeys[key]===cacheKey)continue;
    try{
      if(loadedPdfFonts[key]){
        try{document.fonts.delete(loadedPdfFonts[key])}catch(_){ }
      }
      const face=new FontFace(spec.family,`url(${data})`,{style:'normal',weight:key==='expo'?'400 900':'700'});
      await face.load();
      document.fonts.add(face);
      loadedPdfFonts[key]=face;
      loadedPdfFontKeys[key]=cacheKey;
    }catch(error){
      console.warn(`تعذر تحميل الخط ${spec.family}`,error);
    }
  }
  try{await document.fonts.ready}catch(_){ }
}

function readFileAsDataUrl(file){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>resolve(String(reader.result||''));
    reader.onerror=()=>reject(new Error('تعذر قراءة ملف الخط'));
    reader.readAsDataURL(file);
  });
}

function validFontFile(file){
  if(!file)return false;
  const name=String(file.name||'').toLowerCase();
  return /\.(ttf|otf|woff|woff2)$/.test(name)||/^font\//.test(String(file.type||''));
}

async function saveFontFile(key,file){
  const spec=PDF_FONT_SPECS[key];
  if(!spec||!file)return;
  if(!validFontFile(file)){alert('اختر ملف خط بصيغة TTF أو OTF أو WOFF أو WOFF2.');return}
  if(file.size>MAX_FONT_FILE_SIZE){alert('حجم ملف الخط كبير. الحد الأقصى 2.5 ميجابايت لكل خط.');return}
  const fonts=pdfFontState(),old=clone(fonts[key]);
  try{
    const data=await readFileAsDataUrl(file);
    fonts[key]={name:file.name,data};
    if(!persist())throw new Error('تعذر حفظ الخط داخل المتصفح');
    await ensurePdfFonts(true);
    renderSettings();
    renderPreview();
    toast(`تم حفظ خط بديل لـ ${spec.family} واستخدامه في PDF`);
  }catch(error){
    fonts[key]=old;
    persist();
    alert(error.message||'تعذر حفظ ملف الخط');
  }
}

async function resetPdfFont(key){
  const spec=PDF_FONT_SPECS[key];
  if(!spec)return;
  const fonts=pdfFontState();
  fonts[key]={name:'',data:''};
  if(loadedPdfFonts[key]){
    try{document.fonts.delete(loadedPdfFonts[key])}catch(_){ }
    delete loadedPdfFonts[key];
    delete loadedPdfFontKeys[key];
  }
  persist();
  renderSettings();
  renderPreview();
  toast(`تم الرجوع إلى خط ${spec.family} المدمج`);
}

function bindPdfFontControls(){
  Object.entries(PDF_FONT_SPECS).forEach(([key,spec])=>{
    const input=document.getElementById(spec.uploadId);
    if(input)input.onchange=async e=>{
      const file=e.target.files&&e.target.files[0];
      e.target.value='';
      if(file)await saveFontFile(key,file);
    };
  });
  document.querySelectorAll('[data-reset-font]').forEach(btn=>btn.onclick=()=>resetPdfFont(btn.dataset.resetFont));
}

function waitForQuoteImages(){
  const root=document.getElementById('quotePages');
  if(!root)return Promise.resolve();
  const images=[...root.querySelectorAll('img')];
  return Promise.all(images.map(img=>{
    if(img.complete){
      return typeof img.decode==='function'?img.decode().catch(()=>{}):Promise.resolve();
    }
    return new Promise(resolve=>{
      const done=()=>resolve();
      img.addEventListener('load',done,{once:true});
      img.addEventListener('error',done,{once:true});
    });
  }));
}

async function printQuotePdf(){
  document.documentElement.classList.add('print-preparing');
  try{
    await ensurePdfFonts();
    renderPreview();
    await waitForQuoteImages();
    if(document.fonts)await document.fonts.ready;
    await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
    window.print();
  }catch(error){
    console.error('PDF preparation failed',error);
    window.print();
  }finally{
    setTimeout(()=>document.documentElement.classList.remove('print-preparing'),500);
  }
}

function safePdfFilePart(value){
  return String(value||'')
    .trim()
    .replace(/[\\/:*?"<>|]+/g,'-')
    .replace(/\s+/g,' ')
    .replace(/[. ]+$/g,'')
    .slice(0,80);
}

function quotePdfFileName(){
  const customer=safePdfFilePart(app.draft.customerName);
  const quoteDate=safePdfFilePart(app.draft.quoteDate||today());
  return `عرض سعر${customer?` - ${customer}`:''} - ${quoteDate}.pdf`;
}

function setPdfDownloadBusy(busy){
  ['downloadPdfQuote','downloadPdfTop'].forEach(id=>{
    const btn=document.getElementById(id);
    if(!btn)return;
    if(busy){
      btn.dataset.idleText=btn.textContent;
      btn.textContent='جاري إعداد PDF...';
      btn.disabled=true;
      btn.setAttribute('aria-busy','true');
    }else{
      btn.textContent=btn.dataset.idleText||'حفظ PDF';
      btn.disabled=false;
      btn.removeAttribute('aria-busy');
      delete btn.dataset.idleText;
    }
  });
}

async function downloadQuotePdf(){
  if(typeof window.html2canvas!=='function'||!window.jspdf||typeof window.jspdf.jsPDF!=='function'){
    alert('تعذر تحميل أداة إنشاء PDF. أعد تحميل الصفحة ثم حاول مرة أخرى.');
    return;
  }

  const root=document.documentElement;
  setPdfDownloadBusy(true);
  root.classList.add('pdf-generating');
  toast('جاري إعداد ملف PDF...');

  try{
    await ensurePdfFonts();
    renderPreview();
    await waitForQuoteImages();
    if(document.fonts)await document.fonts.ready;
    await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));

    const pages=[...document.querySelectorAll('#quotePages .quote-page')];
    if(!pages.length)throw new Error('لا توجد صفحات لعرض السعر');

    const {jsPDF}=window.jspdf;
    const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
    pdf.setProperties({
      title:`عرض سعر${app.draft.customerName?` - ${app.draft.customerName}`:''}`,
      subject:'عرض سعر للإقامة والحجز',
      author:app.settings.companyName||'ينابيع الهدى المتميزة',
      creator:'برنامج عروض أسعار ينابيع الهدى'
    });

    for(let index=0;index<pages.length;index++){
      const canvas=await window.html2canvas(pages[index],{
        scale:2,
        useCORS:true,
        allowTaint:false,
        backgroundColor:'#ffffff',
        logging:false,
        imageTimeout:15000,
        width:794,
        height:1123,
        windowWidth:794,
        windowHeight:1123,
        scrollX:0,
        scrollY:0
      });
      if(index>0)pdf.addPage('a4','portrait');
      const imageData=canvas.toDataURL('image/jpeg',0.97);
      pdf.addImage(imageData,'JPEG',0,0,210,297,undefined,'FAST');
      canvas.width=1;
      canvas.height=1;
    }

    const blob=pdf.output('blob');
    const downloadUrl=URL.createObjectURL(blob);
    const link=document.createElement('a');
    link.href=downloadUrl;
    link.download=quotePdfFileName();
    link.rel='noopener';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(()=>URL.revokeObjectURL(downloadUrl),30000);
    toast('تم تنزيل ملف PDF');
  }catch(error){
    console.error('Direct PDF download failed',error);
    alert('تعذر تنزيل ملف PDF مباشرة. يمكنك استخدام زر الطباعة كخيار بديل.');
  }finally{
    root.classList.remove('pdf-generating');
    setPdfDownloadBusy(false);
    updatePreviewScale();
  }
}

function duplicateOffer(id){
  if(app.draft.items.length>=MAX_OFFERS){toast('الحد الأقصى 8 خيارات');return}
  const sourceIndex=app.draft.items.findIndex(item=>item.id===id);
  if(sourceIndex<0){toast('تعذر العثور على الخيار المطلوب');return}
  const copy=clone(app.draft.items[sourceIndex]);
  copy.id=uid();
  app.draft.items.splice(sourceIndex+1,0,copy);
  persist();
  renderAll();
  toast(`تم نسخ الخيار ${sourceIndex+1} بكل بياناته`);
}

let saveTimer;
function autoSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persist();renderPreview()},120)}

function toast(msg){
  const t=document.getElementById('toast');
  if(!t)return;
  t.textContent=msg;
  t.classList.add('show');
  clearTimeout(toast.timer);
  toast.timer=setTimeout(()=>t.classList.remove('show'),2100);
}

function findHotel(name,id=''){
  const key=String(name||'').trim().toLowerCase();
  return HOTELS.find(h=>h.id===id)||HOTELS.find(h=>String(h.name).trim().toLowerCase()===key||String(h.englishName).trim().toLowerCase()===key);
}

function matchingRate(offer){
  const h=findHotel(offer.hotelName,offer.hotelId);
  if(!h)return null;
  const room=String(offer.roomType||'').trim().toLowerCase();
  let candidates=(h.rates||[]).filter(r=>String(r.roomType||'').trim().toLowerCase()===room);
  if(!candidates.length)candidates=h.rates||[];
  const date=offer.checkIn||today();
  const exact=candidates.find((r,i)=>(!r.from||date>=r.from)&&(!r.to||date<r.to||(i===candidates.length-1&&date<=r.to)));
  if(exact)return exact;
  return candidates.slice().sort((a,b)=>Math.abs(new Date(date)-new Date(a.from||date))-Math.abs(new Date(date)-new Date(b.from||date)))[0]||null;
}

function ratePrices(rate){
  if(!rate)return{weekday:'',weekend:''};
  let weekday=String(rate.weekdayPrice||'').trim(),weekend=String(rate.weekendPrice||'').trim();
  if(!weekday&&!weekend){
    const p=String(rate.price||'').split(/[\/|\\]+/).map(x=>x.trim()).filter(Boolean);
    if(p.length===1)weekday=weekend=p[0];
    else if(p.length>1){
      const a=num(p[0]),b=num(p[1]);
      weekday=a&&b?(a<=b?p[0]:p[1]):p[0];
      weekend=a&&b?(a<=b?p[1]:p[0]):p[1];
    }
  }
  return{weekday,weekend:weekend||weekday};
}

function inferView(room){
  const t=String(room||'');
  if(/كعبة|kaaba/i.test(t))return'إطلالة الكعبة';
  if(/حرم|haram/i.test(t))return'إطلالة الحرم';
  if(/سيتي|مدينة|city/i.test(t))return'إطلالة المدينة';
  if(/جزئية|partial/i.test(t))return'إطلالة جزئية';
  if(/بدون|no view/i.test(t))return'بدون إطلالة';
  return'';
}

function applyHotel(offer,hotelId=''){
  const h=findHotel(offer.hotelName,hotelId||offer.hotelId);
  if(!h)return false;
  offer.hotelMode='list';
  offer.hotelId=h.id;
  offer.hotelName=h.name;
  offer.mealPlan=h.mealPlan||offer.mealPlan;
  const r=(h.rates||[])[0];
  if(r)offer.roomType=r.roomType||offer.roomType;
  applyRate(offer);
  return true;
}

function applyRate(offer){
  const r=matchingRate(offer),p=ratePrices(r);
  if(!r)return false;
  offer.weekdayPrice=p.weekday||'';
  offer.weekendPrice=p.weekend||p.weekday||'';
  offer.nightlyPrice=p.weekday||p.weekend||'';
  offer.extraBed=String(r.extraBed??'');
  offer.view=inferView(offer.roomType)||offer.view;

  // Auto-set pricingMode if hotel rates specify weekday vs weekend rates
  if(p.weekday && p.weekend && num(p.weekday) !== num(p.weekend)){
    offer.pricingMode='weekdayWeekend';
  } else if(p.weekday && (!p.weekend || num(p.weekday) === num(p.weekend))){
    offer.pricingMode='nightly';
  }
  return true;
}

function stats(o){
  const start=new Date(`${o.checkIn}T12:00:00`),end=new Date(`${o.checkOut}T12:00:00`);
  if(!o.checkIn||!o.checkOut||isNaN(start)||isNaN(end)||end<=start)return{nights:0,weekday:0,weekend:0,total:0};
  let nights=0,weekday=0,weekend=0;
  for(let d=new Date(start);d<end;d.setDate(d.getDate()+1)){
    nights++;
    const day=d.getDay();
    if(day===5||day===6)weekend++;
    else weekday++;
  }
  let total=o.pricingMode==='weekdayWeekend'?weekday*num(o.weekdayPrice)+weekend*num(o.weekendPrice):o.pricingMode==='total'?num(o.totalPrice):nights*num(o.nightlyPrice);
  return{nights,weekday,weekend,total};
}


function pricingHtml(o){
  if(o.pricingMode==='weekdayWeekend')return`<div class="field"><label>سعر WEEKDAY</label><input inputmode="decimal" data-key="weekdayPrice" value="${esc(o.weekdayPrice)}"></div><div class="field"><label>سعر WEEKEND</label><input inputmode="decimal" data-key="weekendPrice" value="${esc(o.weekendPrice)}"></div>`;
  if(o.pricingMode==='total')return`<div class="field"><label>السعر الكامل للمدة</label><input inputmode="decimal" data-key="totalPrice" value="${esc(o.totalPrice)}"></div><div></div>`;
  return`<div class="field"><label>سعر الليلة</label><input inputmode="decimal" data-key="nightlyPrice" value="${esc(o.nightlyPrice)}"></div><div></div>`;
}

function hotelOptions(selectedId=''){
  return`<option value="">اختر الفندق من القائمة</option>${HOTELS.map(h=>`<option value="${esc(h.id)}" ${h.id===selectedId?'selected':''}>${esc(h.name)}${h.englishName?` — ${esc(h.englishName)}`:''}</option>`).join('')}`;
}

function hotelFieldsHtml(o){
  if(o.hotelMode==='custom')return`<div class="field"><label>اسم الفندق الجديد</label><input data-hotel-custom value="${esc(o.hotelName)}" placeholder="اكتب اسم الفندق" autocomplete="off"></div>`;
  return`<div class="field"><label>الفندق من القائمة</label><select data-hotel-select>${hotelOptions(o.hotelId)}</select></div>`;
}

